head.script:
scwin.checkVal = function() {
    var engineVer = WebSquare.text.BASE64Decode(WebSquare.ver);
    if (engineVer.indexOf("5.0_4") == -1 && parseInt(engineVer.slice(6,11)) > 4800) {
        return inputCalendar.dom.img.style.top === "";
    }
    return parseFloat(output.getValue()) === parseFloat(inputCalendar.dom.img.style.top);
}
scwin.checkVal2 = function() {
    if (inputCalendar.dom.img.style.top !== "") {
        return parseFloat(output.getValue()) === parseFloat(inputCalendar.dom.img.style.top);
    } else {
        return true;
    }
}
scwin.unitTest = function() {
    var setHeight = WebSquare.style.getStyle(inputCalendar.render, 'height');
    setHeight = setHeight == 'auto' ? inputCalendar.render.offsetHeight : parseFloat(setHeight);
    var imgHeight = parseFloat(WebSquare.style.getStyle(inputCalendar.dom.img, 'height'));
    var expectedTop = (setHeight - imgHeight) / 2;
    output.setValue(expectedTop);
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
